57	
58	    #[derive_message_formats]
59	    fn message(&self) -> String {
60	        "Do not pass mutable objects as values to `dict.fromkeys`".to_string()
61	    }
62	
63	    fn fix_title(&self) -> Option<String> {
64	        Some("Replace with comprehension".to_string())
65	    }
66	}
