103	        id: Name::new_static("key"),
104	        ctx: ast::ExprContext::Load,
105	        range: TextRange::default(),
106	        node_index: ruff_python_ast::AtomicNodeIndex::NONE,
107	    };
108	    // Construct `key in keys`.
109	    let comp = ast::Comprehension {
110	        target: key.clone().into(),
111	        iter: keys.clone(),
112	        ifs: vec![],
113	        range: TextRange::default(),
114	        node_index: ruff_python_ast::AtomicNodeIndex::NONE,
115	        is_async: false,
116	    };
117	    // Construct the dict comprehension.
118	    let dict_comp = ast::ExprDictComp {
119	        key: Box::new(key.into()),
120	        value: Box::new(value.clone()),
121	        generators: vec![comp],
122	        range: TextRange::default(),
123	        node_index: ruff_python_ast::AtomicNodeIndex::NONE,
124	    };
125	    generator.expr(&dict_comp.into())
